import{_ as t,H as i,f as s,i as a}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"26 | B+Tree：PostgreSQL的索引是如何建立的？","description":"","frontmatter":{},"headers":[{"level":2,"title":"数据库","slug":"数据库","link":"#数据库","children":[{"level":3,"title":"树状索引","slug":"树状索引","link":"#树状索引","children":[]}]},{"level":2,"title":"B- 树 B+ 树","slug":"b-树-b-树","link":"#b-树-b-树","children":[{"level":3,"title":"B+ 树","slug":"b-树","link":"#b-树","children":[]}]},{"level":2,"title":"插入操作","slug":"插入操作","link":"#插入操作","children":[]},{"level":2,"title":"删除操作","slug":"删除操作","link":"#删除操作","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[{"level":3,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}]}],"relativePath":"业务开发算法50讲/26｜B+Tree：PostgreSQL的索引是如何建立的？.md","filePath":"业务开发算法50讲/26｜B+Tree：PostgreSQL的索引是如何建立的？.md","lastUpdated":1795537005000}'),n={name:"业务开发算法50讲/26｜B+Tree：PostgreSQL的索引是如何建立的？.md"};function p(l,e,h,r,E,o){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_26-b-tree-postgresql的索引是如何建立的" tabindex="-1">26 | B+Tree：PostgreSQL的索引是如何建立的？ <a class="header-anchor" href="#_26-b-tree-postgresql的索引是如何建立的" aria-label="Permalink to &quot;26 | B+Tree：PostgreSQL的索引是如何建立的？&quot;">​</a></h1><p>你好，我是微扰君。</p><p>过去几讲我们学习了一些经典的分布式算法，主要涉及多个节点之间的协作方式，在现在的业务场景下，它们更多被封装在各种中间件或者类库中，直接供我们使用，不过背后的很多思想还是很值得好好学习体悟的。</p><p>从今天开始，我们将更加贴近日常业务开发，剖析常用中间件里用到的、单机上的一些算法，帮助自己更好地分析和优化系统性能。比如在使用数据库的时候，如果我们不清楚底层索引的原理，写出来的查询语句可能性能会很差，甚至不见得能正确建立索引；再比如有时候我们希望不引入额外的网关组件，直接在业务代码里实现一个简单的限流模块，如何设计更合适……</p><p>类似场景还有很多，话不多说，今天我们一起来了解这些中间件的秘密。</p><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><p>我们先从数据库聊起。数据库，应该是我们广大程序员日常开发中必不可少的组件了，作为数据持久化的基石，在互联网应用中，大部分的业务数据都以结构化的方式存储在数据库中，而数据库为我们提供了良好的数据查询、管理、持久化、事务的能力。</p><p>在数据库场景下，我们存储的都是大量的数据，显然没有办法一次性把所有的数据全部加载到内存中，用内存高效的数据结构或者算法进行搜索。那数据库是如何快速查询数据的呢？比如：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> student </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5130309492</span></span></code></pre></div><p>如果我们逐一遍历数据库的每个记录逐个对比，也就是常说的“全表扫描”，查找速度肯定很慢。如何提高查找指定 ID 记录的速度呢？</p><p>通常为了提高查找速度，我们都会设计一种特殊的数据结构，在内存中如此，在磁盘中也不例外。我们需要设计一种适合磁盘场景的数据结构，对业务数据进行某种有序性的维护，在磁盘读写次数不多的情况下，结合内存，就能快速找到需要查询的记录在磁盘中所在的位置。这就是我们常说的“索引”。</p><p>那索引一般是用什么样的数据结构实现的呢？</p><p>其实在之前学习 Kafka的时候，我们学过线性稀疏的索引，适用于 append only 的存储模式，利用有序性带来的二分搜索，帮助我们加速查找指定 offset 的日志内容，你可以再回顾一下理解索引背后用空间换时间的思想。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/1.png" alt=""></a></p><p>但是 kafka 的索引，在数据库的场景下并不好用，因为数据库中，我们随时可能需要删除或者修改某个字段的值，如果要保持索引的线性有序性的要求，就要不断调整索引文件的前后顺序，在磁盘上，这个代价是非常高的。</p><p>所以，为了能适配需要随机修改插入的数据库场景，我们的索引结构不能是线性的了。</p><h3 id="树状索引" tabindex="-1">树状索引 <a class="header-anchor" href="#树状索引" aria-label="Permalink to &quot;树状索引&quot;">​</a></h3><p>如果你熟悉第一章的内容，估计很快就会想到红黑树这样的结构。</p><p>在内存中，红黑树任意字段的查询可以做到 logN 的复杂度，而且相比于二分搜索所需具备的有序性，在红黑树上做元素的调整和增删效率要高得多。我们之前也提到了，对于百万量级的存储场景，红黑树也只需要 20 层这个数量级的高度就可以容纳全部元素。查询效率当然是很有保证的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/2.png" alt=""></a></p><p>那可不可以在数据库的索引中采用红黑树呢？</p><p>因为在数据库中，不同于内存的场景，磁盘读写比内存慢的多，所以相比于查询的计算成本，IO 成本可能要显著的多。</p><p>数据库里存储的数据比较多，如果我们采用二叉树来存储的话，层数必然不会很少，且层和层之间的数据在物理上基本上是不连续的，即使前几层的元素可以被预加载至内存中，我们仍然可能需要在树上进行 10 余次的跳转查询，也就对应着 10 余次的磁盘 IO，这是不可接受的。</p><p>有没有什么办法利用磁盘读写的特性，既可以保持树状结构的灵活性，又同时降低查询的 IO次数呢？这就是 B+ 树的用武之地了，核心就是通过引入更多的分叉，在节点同样数量级的范围内，显著地降低树状索引的层数。</p><h2 id="b-树-b-树" tabindex="-1">B- 树 B+ 树 <a class="header-anchor" href="#b-树-b-树" aria-label="Permalink to &quot;B- 树 B+ 树&quot;">​</a></h2><p>B+ 树是传统关系型数据库索引的标配，在 MySQL、PostgreSQL 等主流 DBMS 中，B+ 树都是索引的底层实现。</p><p>B+ 树是由 B- 树演化而来，这里的 B 一般被解读为 balance，也就是平衡树，和之前介绍的2-3 树差不多，B- 树、B+ 树每个节点也包含多个键和多条链。</p><p>我们先看 B- 树，这个数据结构就是为大量数据的存储和快速访问而设计的。B- 树的每个节点都包含若干个键和若干个指针域，指针域就用于指向存储的数据本身。m 阶 B- 树的主要约束还包括：</p><ol><li><p>所有叶子结点处于同一高度；</p></li><li><p>除了根结点和叶子结点之外，每个节点最少包含 m/2 个键；</p></li><li><p>每个节点最多包含 m-1 个键和 m 条链，如果某个节点有 k-1 个键，则对应 k 条链；</p></li><li><p>每个节点内部的键有序排列，每个链指向的节点中的键，都在链左右节点的确定范围之间；</p></li><li><p>根节点在不为叶子节点的时候至少有两个子节点。</p></li></ol><p>下图就是一个典型 3 阶 B- 树的例子，可以看出，2-3 树是一种特殊的 B- 树。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/3.png" alt=""></a></p><p>在数据库场景下，毫无疑问，我们会把建立索引的字段作为 key，每个 key 后面也会跟上对应记录的指针。</p><p>为什么磁盘上的 B- 树会比对应的二叉平衡树快很多呢？主要就是利用了磁盘访问的局部性原理。</p><p>之前讲 LRU 的时候也提到了相关概念，计算机在读取磁盘的时候，往往是以页为单位读取的，读取某一页中的部分内容和读取该中的全部内容，所花费的代价其实是一样的。如果我们把 B- 树的每个节点中存储的大小设成一个页的大小，利用磁盘预读的能力，就可以做到仅通过一次 IO 就将整个节点的全部内容加载到内存中。</p><p>一个页的大小通常是 4K～16K，能包含的键数可以高达几千条。以 InnoDB 通常采用的 16K大小的页为例，如果我们的索引字段和指针域大小为 8B，B- 树上的每个节点能包含的键数高达 2048 个，这就意味着用 4 层的高度，就可以存储接近 10 亿级别的记录，在索引字段大小更大的时候，我们通常也只需要 5 层以内，就可以构造大部分表的索引。</p><p>这就是多叉的 B 树的主要优点了，利用磁盘的预读能力和树状结构，我们通过 3～5 次磁盘IO 就可以在 10 亿级的数据表中进行快速检索了。</p><p>检索过程的伪代码如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/4.png" alt=""></a></p><p>基本上和 2-3 树或者普通二叉树的检索思路是一致的：从根节点出发进行遍历，如果在某个节点中查到了目标键，直接返回；如果查到的目标值在两个键之间，就进入两键之间的链所指向的节点进行下一层的查找。</p><p>因为每个节点中的键是有序存储的，当我们加载到内存中后，通常也会直接采用二分搜索，整个搜索过程仍然是 logN 这样非常低的复杂度。所以主要耗时还是花费在 IO 中。</p><h3 id="b-树" tabindex="-1">B+ 树 <a class="header-anchor" href="#b-树" aria-label="Permalink to &quot;B+ 树&quot;">​</a></h3><p>通常数据库中采用的索引结构都是 B+ 树，B+ 树和 B- 树的区别主要在于树节点的组织形式，包括两点：</p><ol><li><p>B+ 树的所有的叶子节点之间会通过双向指针串联在一起，构成一个双向链表；</p></li><li><p>B+ 树的中间节点不会存储数据指针，而只有叶子节点才会存储，中间节点只用于存储到叶子节点的路由信息。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/5.png" alt=""></a></p><p>这个图就是一个典型的 3 阶 B+ 树了。可以看到，红色的非叶子节点和绿色的叶子结点的键会有一定的重合，这就是因为非叶子结点不再存储实际的数据信息，所以叶子结点实际上需要存储整张表的信息，但因为树状结构的特性，两者的层数预期仍然都是 logN。</p><p>同时，因为非叶子节点中不再需要存储数据本身相关的信息，每个节点能存储的键的数量也会有所增加，所以 B- 树和 B+ 树的层数期望是差不多的，在大部分业务场景下，3～5 次的 IO查询就可以让我们查询到任意目标值。</p><p>那为什么要引入这样额外的指针和约束呢？主要原因在于在数据库中我们经常需要范围查询，比如这样的查询语句，查询所有年龄小于 20 的学生：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> students </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> age </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span></span></code></pre></div><p>因为 B+ 树的特性，叶子节点之间也一定是有序排列的，我们只需要找到比 20 小的第一个元素，借助双向链表，我们从链表头遍历到这个元素，就能快速获得所有比 20 小的元素。这样高效的范围查询能力是 B- 树所没有的。</p><p>当然了，如果能让叶子结点的指向数据，能在磁盘上连续存储，当然可以获得更好的查询能力，不过这件事情非常困难，似乎没有什么太好的办法。</p><p>好有了 B+ 树这样的结构，我们已经可以做到快速查询了，但是数据库中的元素是会被时刻修改的，如何在增删改操作中维持 B+ 树的性质呢？我们一起来看一下。</p><h2 id="插入操作" tabindex="-1">插入操作 <a class="header-anchor" href="#插入操作" aria-label="Permalink to &quot;插入操作&quot;">​</a></h2><p>为了方便演示和讨论，我们用比较简单的 3 阶 B+ 树来讲解，和 2-3 树的过程非常相似我们重点看如何通过节点的合并和分裂操作，应对树结构的变化。</p><p>假设我们的树一开始只有 1、2 两个键，此时键的数量没有超过单节点能容纳的范围，我们用一个叶子结点就可以表示。</p><p>接下来要加入一个 3 节点，和 2-3 树一样，我们就需要对原来的叶子节点做分裂操作，因为 3阶 B+ 树，每个节点最多能承载的元素就是 2 个。现在多出来一个键，我们就需要把节点中键的中位数取出来，提高到上一层，然后分成左右两个部分，每个部分都包括 m/2 个节点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/6.png" alt=""></a></p><p>这里，对于 3 阶 B+ 树而言，左子节点就分到一个键，右子节点则分到两个键。叶子节点间，我们同样需要用双链表的方式进行串联。</p><p>我们尝试继续添加键，现在添加键 4 到树里，首先要做的就是进行前面提到的 B 树的查询，我们会查询到最右侧的叶子结点，从而试图将键 4 放入 (2,3) 构成的节点中，但同样由于每个节点最多存放 2 个键，所以我们需要把 3 提高到上一层，把原来的节点拆成 2 和 (3,4) 两个节点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/7.png" alt=""></a></p><p>后面的添加就是类似的过程，如果继续添加键 5，同样会先放入 (3,4) 节点中，把 4 提高到根节点，而根节点也已经“满载”了，所以会把中间值 3 提到更上一层，此时我们就得到了一个三层的树。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/8.png" alt=""></a></p><p>整个分裂节点的过程自底向上递归进行，可以注意到所有叶子节点的高度其实是始终不变的。</p><h2 id="删除操作" tabindex="-1">删除操作 <a class="header-anchor" href="#删除操作" aria-label="Permalink to &quot;删除操作&quot;">​</a></h2><p>删除操作看起来要稍微复杂一点，不能简单理解成插入过程的逆过程。我们用刚才构造出的树来演示几种不同的删除操作。</p><p>首先我们尝试删除键 2。因为存储 2 的节点本身只存储了一个键，如果删去，2 节点所存储的键数量不满足约束条件了，这个时候我们有两种选择：</p><ul><li><p>一种是如果本身左侧的兄弟节点存储有多余的键，比如存储了 2 个键，我们就可以很简单地直接借用一个键；</p></li><li><p>另一种则需要让父节点下移，并合并子节点。</p></li></ul><p>在这个例子中，左侧存放 key1 的节点也只有一个键，所以不满足可以借用的情况，我们只能考虑让父节点 3 下沉，和 4 节点合并。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/9.png" alt=""></a></p><p>这样我们就可以重新得到一颗平衡的 B+ 树了。每次让父节点下沉，也可能重新破坏父节点的约束条件，我们同样要递归地找左侧兄弟节点借用键或者考虑让更上层的父亲节点下沉，直到整颗树满足约束为止。</p><p>第二种我们继续在这棵树上删除键 5，这个情况比较简单，可以直接删除键 5，并不会破坏原来的约束。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%B8%9A%E5%8A%A1%E5%BC%80%E5%8F%91%E7%AE%97%E6%B3%9550%E8%AE%B2/images/26/10.png" alt=""></a></p><p>在数据库中数据有插入或者删除的时候，我们就可以及时地调整索引内部的结构了。当然可以想见这其中会有很多并发的问题，比较复杂，通常需要加锁解决，也是研究的热点之一，这次就不展开讨论了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们一起学习了非常经典的索引实现方式，利用空间换时间的思路，通过为数据表建立额外的有序索引结构，做到大大加速查询的效果。</p><p>由于数据库需要经常对数据进行增删改，我们的索引数据结构要能高效地变动，而且数据库本身海量的数据也意味着，索引结构不会只存在内存中，需要在二级存储中存储。相比于传统的二叉搜索树，通过 B+ 树，我们可以让整个树状结构变得更加矮胖，而磁盘的预读特性每次都可以加载一整个节点中全部的键，到内存进行二分查找，这样我们只需要通过 3～5 次的磁盘IO 就可以查询加了索引的字段，非常高效。</p><p>B+ 树，相比于 B- 树的主要特点就是，只在叶子结点存储数据，而且叶子节点间用首尾相连的指针串联成双向链表，可以获得良好的范围查询的效果，背后的本质就是索引和数据的分离，这同样是非常值得好好体会的一种思想。</p><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>我们说平衡树的约束之一是每个节点的键不能少于 m/2 也不能多于 m，这里 m/2 是怎么来的呢？ 不知道你有没有深入思考过，如果能回答清楚这个问题，我想你对 B+ 树索引的分裂策略就理解地很深刻了。</p><p>欢迎你在评论区留下你的思考，如果觉得有帮助的话，也欢迎你把这篇文章转给你身边的好朋友，一起学习。下节课见。</p>',79)])])}const c=t(n,[["render",p]]);export{B as __pageData,c as default};
